import pytest

from minisheet.refs import Ref, parse_range, parse_ref, to_a1


# Review Focus
def test_a01_rejected():
    with pytest.raises(ValueError):
        parse_ref("A01")


def test_range_bare_cell():
    with pytest.raises(ValueError):
        parse_range("A1")


def test_to_a1_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(702, 0))


# B§1 table rows
def test_parse_ref_b12():
    assert parse_ref("B12") == Ref(1, 11, False, False)


def test_parse_ref_absolute_max():
    assert parse_ref("$zz$9999") == Ref(701, 9998, True, True)


def test_parse_range_mixed_flags():
    assert parse_range("$C3:A$1") == (Ref(0, 0, False, True), Ref(2, 2, True, False))


def test_to_a1_abs_col():
    assert to_a1(Ref(26, 0, True, False)) == "$AA1"


@pytest.mark.parametrize("s", ["A0", "AAA1"])
def test_parse_ref_invalid_table_rows(s):
    with pytest.raises(ValueError):
        parse_ref(s)


# Further B§1 behaviour
@pytest.mark.parametrize("s", ["A0", "A01", "AAA1", "A10000", "1A", "A1:B2", " A1", "A1 ", "$$A1", ""])
def test_parse_ref_rejects_malformed(s):
    with pytest.raises(ValueError):
        parse_ref(s)


def test_parse_ref_first_and_last_column():
    assert parse_ref("A1") == Ref(0, 0)
    assert parse_ref("Z1") == Ref(25, 0)
    assert parse_ref("AA1") == Ref(26, 0)
    assert parse_ref("ZZ1") == Ref(701, 0)


def test_parse_ref_lowercase_accepted():
    assert parse_ref("c3") == Ref(2, 2)


def test_parse_range_single_cell_valid():
    assert parse_range("A1:A1") == (Ref(0, 0), Ref(0, 0))


def test_parse_range_normalizes_corners():
    assert parse_range("B2:A1") == (Ref(0, 0), Ref(1, 1))


def test_parse_range_tie_uses_first_corner_flags():
    assert parse_range("$A$1:A1") == (Ref(0, 0, True, True), Ref(0, 0, True, True))


@pytest.mark.parametrize("s", ["A1:", ":B2", "A1:B2:C3", "A1:0", "A1;B2"])
def test_parse_range_rejects_malformed(s):
    with pytest.raises(ValueError):
        parse_range(s)


def test_to_a1_plain():
    assert to_a1(Ref(0, 0)) == "A1"
    assert to_a1(Ref(701, 9998)) == "ZZ9999"


def test_to_a1_abs_row_only():
    assert to_a1(Ref(1, 4, False, True)) == "B$5"


def test_to_a1_both_abs():
    assert to_a1(Ref(701, 9998, True, True)) == "$ZZ$9999"


def test_to_a1_row_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(0, 9999))
    with pytest.raises(ValueError):
        to_a1(Ref(0, -1))


def test_to_a1_negative_col():
    with pytest.raises(ValueError):
        to_a1(Ref(-1, 0))


def test_round_trip():
    for s in ["A1", "Z26", "AA27", "$BC$120", "ZZ9999"]:
        assert to_a1(parse_ref(s)) == s.upper()

